import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0013 — contraction-structure search (the generalization)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/plans/0013-contraction-search.md","filePath":"vendored/graphopt/project/plans/0013-contraction-search.md"}`),a={name:`graphopt/project/plans/0013-contraction-search.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0013-—-contraction-structure-search-the-generalization" tabindex="-1">Plan 0013 — contraction-structure search (the generalization) <a class="header-anchor" href="#plan-0013-—-contraction-structure-search-the-generalization" aria-label="Permalink to “Plan 0013 — contraction-structure search (the generalization)”">​</a></h1><p>Status: draft. The one-line version: stop rewriting op-trees; search the <em>contraction structure</em> of the model&#39;s string diagram.</p><h2 id="the-reframe" tabindex="-1">The reframe <a class="header-anchor" href="#the-reframe" aria-label="Permalink to “The reframe”">​</a></h2><p>Every existing law is a special case of &quot;contract the diagram differently&quot;:</p><ul><li>pairing = merge two fan-in branches at a shared leaf</li><li>weight-chain fold = contract the param-only subtree first</li><li>KV latent share = restructure a family to contract through a shared factor</li><li>morphism windows = contract a block subsequence to a single morphism</li></ul><p>The general problem — <em>find the optimal contraction/composition of the model&#39;s monoidal diagram</em> — subsumes them and is NP-hard in general (optimal tensor-network contraction), but the morphism layer already collapses blocks to signature objects, so the search runs on a ~N-node graph, not a ~10k-enode graph.</p><h2 id="what-this-unlocks" tabindex="-1">What this unlocks <a class="header-anchor" href="#what-this-unlocks" aria-label="Permalink to “What this unlocks”">​</a></h2><p>Discovery instead of matching: &quot;does this model contain an MLA-style sharing&quot; becomes a search answer, not a hand-written law. The law library stops being the coverage bottleneck.</p><h2 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to “Stages”">​</a></h2><ol><li><strong>Diagram IR</strong> — model → hypergraph/monoidal diagram over the morphism layer (blocks = nodes, wires = shared tensor edges, multi-arity edges included).</li><li><strong>Contraction moves</strong> — a small move set (merge-projection, factor-shared-subtree, reorder-composition, split-shared-leaf) operating on the diagram; each move reifies to existing certified term rewrites (witness machinery reused).</li><li><strong>Search</strong> — bounded lookahead + e-graph over diagram states (morphism-level, polynomial); cost model prices the reified term.</li><li><strong>Verification</strong> — every delivered move is still a certified rewrite; bounded mode composes.</li><li><strong>RL guidance (later)</strong> — once the space exists, a learned policy over move selection; deterministic verify = clean reward.</li></ol><h2 id="honest-risks" tabindex="-1">Honest risks <a class="header-anchor" href="#honest-risks" aria-label="Permalink to “Honest risks”">​</a></h2><ul><li>Contraction-order search is NP-hard; morphism collapse is the answer but coverage is signature-bounded (multi-input blocks needed first — in flight).</li><li>The wins remain structure-conditional (census: stock dense models are thin) — the value is turning &quot;does this model have structure&quot; into a search result.</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};